function previousWeekDate(){const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-7);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function renderWorkoutSessionHistory(){
 const box=$('workoutSessionHistory'),chart=$('workoutDurationChart'),dayChart=$('workoutDayChart'),pie=$('workoutCompletionPie');if(!box||!chart)return;
 const sessions=Object.entries(state.workoutSessions||{}).filter(([d,s])=>s.saved||Number(s.minutes)>0||(s.completed&&s.completed.length)).sort((a,b)=>a[0].localeCompare(b[0]));
 box.innerHTML=sessions.length?sessions.slice().reverse().map(([d,s])=>'<div class="entry"><div><strong>'+esc(dateLabel(d))+'</strong><small>'+(s.completed?s.completed.length:0)+'/'+(s.plannedCount||'?')+' exercises checked · '+esc(s.notes||s.dayType||'Session')+'</small></div><strong>'+(s.minutes?esc(s.minutes)+' min':'No duration')+'</strong></div>').join(''):'No sessions recorded yet.';
 const ms=sessions.filter(([d,s])=>Number(s.minutes)>0).slice(-14);
 if(ms.length<2){chart.classList.add('empty');chart.textContent=ms.length?'One session saved: '+ms[0][1].minutes+' minutes. Save another timed session to draw the trend graph.':'Save activity duration each day to build your trend graph.';}
 else{const max=Math.max(...ms.map(x=>Number(x[1].minutes))),min=Math.min(...ms.map(x=>Number(x[1].minutes))),range=Math.max(1,max-min),pts=ms.map((x,i)=>({x:18+i*364/Math.max(1,ms.length-1),y:180-(Number(x[1].minutes)-min)/range*130}));chart.classList.remove('empty');chart.innerHTML='<svg viewBox="0 0 400 210" role="img" aria-label="Daily activity duration trend"><line x1="10" y1="180" x2="390" y2="180" stroke="#3a4539"/><polyline fill="none" stroke="#b9f36b" stroke-width="3" points="'+pts.map(p=>p.x+','+p.y).join(' ')+'"/>'+pts.map((p,i)=>'<circle cx="'+p.x+'" cy="'+p.y+'" r="4" fill="#b9f36b"><title>'+esc(ms[i][0])+': '+ms[i][1].minutes+' min</title></circle>').join('')+'<text x="12" y="202" fill="#a8b2a4" font-size="10">'+esc(ms[0][0])+'</text><text x="388" y="202" text-anchor="end" fill="#a8b2a4" font-size="10">'+esc(ms[ms.length-1][0])+'</text></svg>';}
 if(dayChart){const names=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const vals=names.map((n,i)=>{const day=(i+1)%7;return sessions.filter(([d,s])=>new Date(d+'T12:00:00').getDay()===day).reduce((sum,row)=>sum+(Number(row[1].minutes)||0),0)});const top=Math.max(1,...vals);dayChart.innerHTML='<div class="weekday-bars">'+names.map((n,i)=>'<div class="weekday-col"><strong>'+vals[i]+'</strong><div class="weekday-bar" style="height:'+Math.max(4,vals[i]/top*110)+'px"></div><small>'+n+'</small></div>').join('')+'</div>';dayChart.classList.toggle('empty',sessions.length===0);}
 if(pie){let done=0,planned=0;sessions.forEach(([d,s])=>{done+=(s.completed?s.completed.length:0);planned+=(Number(s.plannedCount)||0)});const pct=Math.round(done/Math.max(1,planned)*100);pie.innerHTML=planned?'<div class="pie-wrap"><div class="completion-pie" style="--done:'+pct+'%"></div><div><p><strong>'+done+'</strong> exercises completed</p><p><strong>'+Math.max(0,planned-done)+'</strong> not checked</p><p>'+pct+'% completion</p></div></div>':'Tick and save planned exercises to build your completion pie chart.';pie.classList.toggle('empty',planned===0);}
}
function planForToday(plan){
 if(!plan)return 'Save your weekly workout plan above.';
 const names=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
 const todayName=new Date().toLocaleDateString('en-US',{weekday:'long'});
 const lines=String(plan).split(/\r?\n/);
 let active=false,found=false,items=[];
 for(const raw of lines){
  const line=raw.trim();
  const head=line.match(/^(?:#{1,6}\s*)?(MONDAY|TUESDAY|WEDNESDAY|THURSDAY|FRIDAY|SATURDAY|SUNDAY)\b/i);
  if(head){
   const d=head[1][0].toUpperCase()+head[1].slice(1).toLowerCase();
   if(active)break;
   if(d===todayName){active=true;found=true;items.push('<h4>'+esc(line.replace(/^#+\s*/,''))+'</h4>');}
   continue;
  }
  if(active&&line&&!/^[-_━—]{3,}$/.test(line)&&!/^(morning|evening):?$/i.test(line)&&!/^keep Friday/i.test(line)){
   items.push('<p>'+esc(line)+'</p>');
  }
 }
 if(!found)return '<p>Weekly plan saved. No section found for '+esc(todayName)+'.</p>';
 if(!items.length||items.length===1)return '<h4>'+esc(todayName)+' — Rest day</h4><p>Recovery today. No workout exercises planned.</p>';
 const rest=/\brest\b|recovery/i.test(items.slice(1).map(x=>x.replace(/<[^>]*>/g,'')).join(' '));
 return items.join('')+(rest?'<p class="hint">Recovery day — no strength workout planned.</p>':'');
}
