function closeFoodPortion(){ $('foodPortionModal').hidden=true;document.body.style.overflow='';pendingFood=null;}
function selectedPortion(){
 const cat=foodCategory(pendingFood);let base=pendingFood,grams=100,extraOil=0,displayName=pendingFood.name,stateName=pendingFood.state||'Raw';
 if(cat==='beverage'){
  const tea=/\b(tea|chai)\b/.test(pendingFood.name.toLowerCase()),style=$('beverageStyle').value,size=Number($('beverageSize').value),milk=Number($('beverageMilk').value),sugarChoice=$('beverageSugar').value,sugar=sugarChoice==='custom'?Math.max(0,Number($('beverageCustomSugar').value)||0):Number(sugarChoice),source=$('beverageSource').value;
  grams=size;const black=style==='black'||style==='green';const milkGrams=black?0:Math.min(milk,size);const milkCal=milkGrams*.61;const sugarCal=sugar*4;const drinkBase=tea?(style==='green'?1:2): (style==='black'?2:style==='latte'?Math.max(25,milkCal):3);
  const estimatedCal=drinkBase+milkCal+sugarCal;const name=(tea?(style==='green'?'Green tea':style==='black'?'Black tea':'Indian milk chai'):(style==='black'?'Black coffee':style==='latte'?'Cafe latte':'Milk coffee'))+' ('+size+' ml, '+(sugar===0?'no sugar':sugar+' g sugar')+', '+source+')';
  return {name,state:'Prepared drink · estimated',grams,calories:Math.round(estimatedCal*10)/10,protein:Math.round(milkGrams*.032*10)/10,carbs:Math.round((milkGrams*.048+sugar)*10)/10,fat:Math.round(milkGrams*.033*10)/10,meal:$('foodMealSelect')?.value||'Breakfast'};
 }else if(cat==='egg'){
  const type=$('portionEggType').value,count=Math.max(1,Number($('portionCount').value)||1),prep=$('portionPrep').value;
  grams=count*(type==='white'?33:type==='yolk'?17:50);
  const key=type==='white'?'Egg white, raw':type==='yolk'?'Egg yolk, raw':prep==='boiled'?'Egg, whole, boiled':prep==='omelette'?'Egg omelette':'Egg, whole, raw';
  base=starter.find(x=>x.name===key)||pendingFood;
  if(prep==='fried'||prep==='scrambled')extraOil=Math.max(0,Number($('portionOil').value)||0);
  else if(prep==='omelette')extraOil=Math.max(0,Number($('portionOil').value)||0);
  displayName=(type==='white'?'Egg white':type==='yolk'?'Egg yolk':'Whole egg')+(count===1?'':' × '+count)+' ('+prep+')';stateName=prep==='raw'?'Raw':'Cooked';
 }else if(cat==='rice'){
  grams=Math.max(1,Number($('portionGrams').value)||1);const type=$('portionRiceType').value,st=$('portionRiceState').value;
  base=starter.find(x=>x.name==='Rice, '+type+', '+(st==='cooked'?'cooked':'raw'))||pendingFood;
  displayName=(type==='white'?'White rice':'Brown rice')+' ('+(st==='cooked'?'cooked':'dry/raw')+')';stateName=st==='cooked'?'Cooked':'Raw';
 }else if(cat==='sugar'){
  grams=Math.max(1,Number($('portionGrams').value)||1);const type=$('portionSugarType').value;base=starter.find(x=>x.name==='Sugar, '+type)||pendingFood;displayName=type==='white'?'White sugar':'Brown sugar';stateName='Raw';
 }else{
  grams=Math.max(1,Number($('portionGrams').value)||1);const prep=$('portionPrep').value;extraOil=Math.max(0,Number($('portionOil')?.value)||0);
  const n=pendingFood.name.toLowerCase();
  if(cat==='potato'){
   if(prep==='airfried')base=starter.find(x=>x.name==='Potato, air-fried, no oil')||pendingFood;
   else if(prep==='deepfried')base=starter.find(x=>x.name==='French fries, deep-fried')||pendingFood;
   else if(prep==='boiled')base=starter.find(x=>x.name==='Potato, boiled')||pendingFood;
   else if(prep==='roasted')base=starter.find(x=>x.name==='Potato, air-fried, no oil')||pendingFood;
   if(prep==='deepfried')extraOil=0;
   displayName=(prep==='airfried'?'Air-fried potato':prep==='deepfried'?'French fries (deep-fried)':prep==='boiled'?'Boiled potato':'Roasted potato');stateName='Cooked';
  }else{
   if(n.includes('chicken')&&prep!=='aslisted'&&prep!=='boiled')base=starter.find(x=>x.name==='Chicken breast, cooked')||pendingFood;
   displayName=pendingFood.name+(prep==='aslisted'?'':' ('+prep+')');stateName=base.state||stateName;
  }
 }
 const factor=grams/100,oilCal=extraOil*9;
 return {name:displayName,state:stateName,grams,calories:Math.round(((base.cal||0)*factor+oilCal)*10)/10,protein:Math.round((base.p||0)*factor*10)/10,carbs:Math.round((base.c||0)*factor*10)/10,fat:Math.round(((base.f||0)*factor+extraOil)*10)/10,meal:$('foodMealSelect')?.value||'Breakfast'};
}
