$('openWeightNotebook')?.addEventListener('click',()=>{const n=$('weightNotebook');n.hidden=!n.hidden;$('openWeightNotebook').textContent=n.hidden?'📘 Open weight history notebook':'📕 Close weight history notebook';});
$('weightGoalForm')?.addEventListener('submit',e=>{e.preventDefault();if(state.weightGoal!==null)return;const v=Number($('weightGoalInput').value);if(!Number.isFinite(v)||v<20||v>400)return;state.weightGoal=v;state.settings.targetWeight=v;save();$('weightGoalStatus').textContent='🐾 Goal weight saved and locked. You’re all set — view your graph or records. Come back tomorrow for your next update.';});
$('dayOneWeightForm')?.addEventListener('submit',e=>{e.preventDefault();if(state.dayOneWeight)return;const w=Number($('dayOneWeightInput').value);if(!Number.isFinite(w)||w<20||w>400)return;state.dayOneWeight={date:today(),weight:w,waist:$('dayOneWaistInput').value?Number($('dayOneWaistInput').value):null};if(!state.weights.some(x=>x.date===today()))state.weights.push({id:crypto.randomUUID(),date:today(),weight:w,waist:state.dayOneWeight.waist,notes:'Day 1 baseline'});save();$('dayOneWeightStatus').textContent='🐾 Day 1 saved and locked. You’re all set — view your graph or records. Come back tomorrow for your next update.';});
$('weightForm').addEventListener('submit',e=>{e.preventDefault();if(state.weights.some(x=>x.date===today())){e.target.style.display='none';$('weightJourneySummary').textContent='🐾 Today’s weight is already saved. Come back tomorrow for your next update — your graph and records are ready below.';return;}state.weights.push({id:crypto.randomUUID(),date:today(),weight:Number($('weightInput').value),waist:$('waistInput').value?Number($('waistInput').value):null,notes:$('weightNotes').value.trim()});e.target.reset();save();e.target.style.display='none';$('weightJourneySummary').textContent='🐾 Today’s data has been saved. Come back tomorrow for your next update. View your graph or records below.';});
